{
  "status": "SUPPORTED",
  "task_summary": "Set up refreshment stations near seating and position the remote for shared access.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds beverage and/or food for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["cup and plate", "snack tray", "drink container"],
        "required_properties": ["holds consumable"]
      },
      {
        "id": "remote_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["TV remote", "media controller"],
        "required_properties": ["activates television"]
      },
      {
        "id": "side_table",
        "entity_kind": "REGION",
        "function": "Surface near a seat for placing refreshments.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["end table", "side table", "small table"],
        "required_properties": ["flat surface", "adjacent to seating"]
      },
      {
        "id": "central_surface",
        "entity_kind": "REGION",
        "function": "Shared surface for the remote control.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["coffee table", "center table", "desk"],
        "required_properties": ["flat surface", "accessible to multiple viewers"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_placement",
        "relation": "The refreshment_setting must be located on or immediately next to the side_table.",
        "participant_roles": ["refreshment_setting", "side_table"]
      ,
        "required": true
      },
      {
        "id": "remote_placement",
        "relation": "The remote_control must be located on the central_surface.",
        "participant_roles": ["remote_control", "central_surface"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "setup_refreshments",
        "operation": "Place the refreshment_settings onto the side_tables.",
        "participant_roles": ["refreshment_setting", "side_table"],
        "operation_count": 2
      },
      {
        "id": "move_remote",
        "operation": "Move the remote_control onto the central_surface.",
        "participant_roles": ["remote_control", "central_surface"],
        "operation_count": 1
      }
    ]
  },
